head.b:skin:
body {
    font-family: 'Inter', sans-serif;
    background-color: #e6dfd1; /* Warna kertas koran/arsip usang kuno */
    background-image: radial-gradient(#d9cfbc 1px, transparent 0);
    background-size: 24px 24px;
    transition: all 0.3s ease;
}
.font-serif {
    font-family: 'Playfair Display', serif;
}
/* Custom Scrollbar bertema antik */
.custom-scrollbar::-webkit-scrollbar {
    width: 6px;
}
.custom-scrollbar::-webkit-scrollbar-track {
    background: #d6cdbc;
}
.custom-scrollbar::-webkit-scrollbar-thumb {
    background: #9c8f75;
    border-radius: 3px;
}
/* Style Elemen Khusus untuk Vibe Jadul */
.vintage-panel {
    background-color: #f4efe4 !important; /* Warna kertas linen tua */
    border: 1px solid #c5b89d !important;
}
.vintage-input {
    background-color: #ebdcb9 !important;
    border: 1px solid #bda880 !important;
    color: #383020 !important;
}
.vintage-input::placeholder {
    color: #8c7d60 !important;
}
/* Mode Zen Khusus */
body.zen-mode-active {
    background-color: #121214 !important;
    background-image: none !important;
}
body.zen-mode-active header, 
body.zen-mode-active footer, 
body.zen-mode-active #layar1-section {
    display: none !important;
}
body.zen-mode-active #layar2-section {
    grid-column: span 12 / span 12 !important;
}

body.script:
//
var conditionModifiers = {
    'pristine': 'well-preserved, clean plate, archival museum quality, untouched',
    'faded': 'faded chemistry, heavily low-contrast, muted tones, sepia-bleached, dusty silver coating',
    'damaged': 'severely torn edges, deep scratches on emulsion, cracked glass plate, tattered paper texture, water stains',
    'burned': 'partially burned edges, scorched paper borders, singed emulsion, fire-damaged celluloid artifacts',
    'all-effects': 'randomized deterioration, aged paper rot, water damage, scorched corner, heavily scratched negatives'
};

var timelineData = {
    era_1: {
        name: "1826-1827: Early Camera Obscura & Bitumen Era",
        tech: "Niépce heliography method, bitumen of Judea on pewter plate, experimental chemical coating",
        lighting: "8-hour continuous daylight exposure, shifting sun directions, high-contrast harsh direct shadows",
        camera_spec: "Primitive wooden camera obscura box, no optical lens correction, experimental focus",
        start_year: 1826, end_year: 1827
    },
    era_2: {
        name: "1839: Daguerreotype & Commercial Dawn",
        tech: "Louis Daguerre technique, highly polished iodized silver-plated copper, mercury vapor development",
        lighting: "3-to-15 minutes intense studio skylight illumination, stark side lighting, stiff headrests utilized",
        camera_spec: "Giroux Daguerreotype camera, Chevalier acromatic lens, razor-sharp central detail, mirror-like metallic sheen",
        start_year: 1839, end_year: 1845
    },
    era_3: {
        name: "1888: Eastman Kodak Flexible Film Revolution",
        tech: "Early nitrocellulose flexible roll film, circular mask snapshot framing, grainy black and white silver halide emulsion",
        lighting: "Casual outdoor snapshots, natural erratic lighting, unposed candid illumination",
        camera_spec: "Original Kodak No. 1 box camera, fixed-focus barrel lens, rapid shutter speed instantaneous exposure",
        start_year: 1888, end_year: 1895
    },
    era_4: {
        name: "Vintage Vibe & Mid-Century Aesthetics",
        tech: "Classic vintage monochrome, early autochrome color shifts, organic gelatin silver fiber prints",
        lighting: "Soft nostalgic cinematic shadows, timeless retro atmosphere, low fidelity tonal range",
        camera_spec: "Classic analog twin-lens reflex (TLR) or rangefinder camera, vintage coated glass optics",
        start_year: 1930, end_year: 1955
    }
};

var months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function generateFakeDate(startYear, endYear) {
    var randDay = Math.floor(Math.random() * 28) + 1; 
    var randMonth = months[Math.floor(Math.random() * 12)];
    var randYear = Math.floor(Math.random() * (endYear - startYear + 1)) + startYear;
    return randDay + " " + randMonth + " " + randYear;
}

function updateImageSimilarityView(val) {
    document.getElementById('imageSimilarityVal').innerText = val + '%';
}

// Interseptor visual nilai teks slider pose semantik
function getPoseModifier(val) {
    var numeric = parseInt(val);
    if (numeric <= 25) {
        return { label: "Candid & Natural (Bebas)", phrase: "unposed candid look, captured in motion, figures looking away from the camera lens" };
    } else if (numeric <= 50) {
        return { label: "Semi Formal (Medium)", phrase: "relaxed stance, realistic vintage posture, natural human anatomical composition" };
    } else if (numeric <= 75) {
        return { label: "Studio Portrait (Klasik)", phrase: "stiff vintage studio pose, figures looking directly into the historical lens camera setup" };
    } else {
        return { label: "Rigid Formal (Sangat Kaku)", phrase: "extremely rigid formal historical posing, head-and-shoulders alignment, absolute steady composition" };
    }
}

function updatePoseStyleView(val) {
    var poseData = getPoseModifier(val);
    document.getElementById('poseStyleVal').innerText = poseData.label;
}

// Interseptor visual nilai teks slider penuaan semantik
function getAgeModifier(val) {
    var numeric = parseInt(val);
    if (numeric <= 15) {
        return { label: "Youthful (Fresh Faced)", phrase: "fictional historical fresh-faced youthful presentation, clear young features" };
    } else if (numeric <= 30) {
        return { label: "Young Adult (Early Twenties)", phrase: "fictional historical young adult appearance, vibrant thirties features, early wrinkles" };
    } else if (numeric <= 50) {
        return { label: "Mature Adult (Thirties)", phrase: "fictional historical mature prime-of-life appearance, established adult features, early subtle lines" };
    } else if (numeric <= 75) {
        return { label: "Middle Aged (Characterized by Time)", phrase: "fictional historical middle-aged depiction, maturity of time, expression lines and character" };
    } else {
        return { label: "Extremely Aged (Distinguished)", phrase: "fictional historical elderly distinguished depiction, deep wrinkles, fragile historical beauty" };
    }
}

function updateAgeStyleView(val) {
    var ageData = getAgeModifier(val);
    document.getElementById('ageStyleVal').innerText = ageData.label;
}

function generateHistoricalPrompts() {
    var subject = document.getElementById('subjectInput').value.trim() || "An untold historical scene";
    var attachedImageUrl = document.getElementById('imageUrlInput').value.trim();
    var imgSimilarityWeight = document.getElementById('imageSimilarityInput').value;
    var poseValue = document.getElementById('poseStyleInput').value;
    var ageValue = document.getElementById('ageStyleInput').value;
    var chosenCondition = document.getElementById('conditionInput').value;
    var conditionText = conditionModifiers[chosenCondition];

    var outputContainer = document.getElementById('jsonOutputArea');
    outputContainer.innerHTML = '';

    var calculatedImageWeight = (parseInt(imgSimilarityWeight) / 50).toFixed(2);
    var currentPoseObj = getPoseModifier(poseValue);
    var currentAgeObj = getAgeModifier(ageValue);
    var promptCounter = 1;
    var eras = Object.keys(timelineData);

    for (var e = 0; e < eras.length; e++) {
        var eraKey = eras[e];
        var era = timelineData[eraKey];

        var eraHeader = document.createElement('div');
        eraHeader.className = 'pt-4 pb-2 border-b border-stone-800 text-amber-400 font-serif font-medium text-sm sticky top-0 bg-zinc-950 z-10 flex justify-between items-center';
        eraHeader.innerHTML = '<span>' + era.name + '</span> <span class="text-xs font-mono text-zinc-500">26 Prompts</span>';
        outputContainer.appendChild(eraHeader);

        for (var i = 1; i <= 26; i++) {
            var styleVariant = "";
            var conditionSelector = conditionText;

            if (chosenCondition === 'all-effects') {
                var keys = Object.keys(conditionModifiers);
                conditionSelector = conditionModifiers[keys[Math.floor(Math.random() * 4)]];
            }

            var mod = i % 5;
            if (mod === 0) styleVariant = "Cinematic documentary style capturing " + subject + ", tracking shot perspective. Physical presentation: " + currentPoseObj.phrase + ", with " + currentAgeObj.phrase + ".";
            else if (mod === 1) styleVariant = "Close-up raw macro detail focusing on " + subject + ". Physical presentation: " + currentPoseObj.phrase + ", with " + currentAgeObj.phrase + ".";
            else if (mod === 2) styleVariant = "Wide-angle establishing shot showcasing " + subject + " in its raw environment. Physical presentation: " + currentPoseObj.phrase + ", with " + currentAgeObj.phrase + ".";
            else if (mod === 3) styleVariant = "Atmospheric chiaroscuro study of " + subject + ", deep artistic shadows. Physical presentation: " + currentPoseObj.phrase + ", with " + currentAgeObj.phrase + ".";
            else if (mod === 4) styleVariant = "Authentic museum archival record photo of " + subject + ", flat layout look. Physical presentation: " + currentPoseObj.phrase + ", with " + currentAgeObj.phrase + ".";

            var fakePhotoDate = generateFakeDate(era.start_year, era.end_year);
            var dateContextPrefix = "An authentic archival photograph document dated on " + fakePhotoDate + ", depicting ";

            var fullPrompt = "";
            if (attachedImageUrl !== "") {
                fullPrompt = attachedImageUrl + " " + dateContextPrefix + styleVariant + " Photographed using " + era.tech + ". Technical setup: " + era.camera_spec + ", under " + era.lighting + ". Photographic condition: " + conditionSelector + ". Masterpiece historical rendering --ar 4:3 --iw " + calculatedImageWeight + " --v 6.0";
            } else {
                fullPrompt = dateContextPrefix + styleVariant + " Photographed using " + era.tech + ". Technical setup: " + era.camera_spec + ", under " + era.lighting + ". Photographic condition: " + conditionSelector + ". Masterpiece historical rendering --ar 4:3 --v 6.0";
            }

            var padId = String(promptCounter);
            while (padId.length < 3) { padId = "0" + padId; }
            var promptId = "PRMPT-" + padId;

            var singlePromptObj = {
                id: promptId,
                era_reference: eraKey,
                variant_style: "Option #" + i,
                photo_taken_date: fakePhotoDate, 
                assigned_pose_type: currentPoseObj.label,
                assigned_age_semantic: currentAgeObj.label, 
                image_reference_url: attachedImageUrl !== "" ? attachedImageUrl : "none",
                image_similarity_weight: attachedImageUrl !== "" ? imgSimilarityWeight + "%" : "not applicable",
                prompt_string: fullPrompt
            };

            var jsonString = JSON.stringify(singlePromptObj, null, 4);

            var card = document.createElement('div');
            card.className = 'bg-stone-900 border border-stone-800 rounded-lg p-4 flex flex-col gap-3 shadow-md hover:border-stone-700 transition-all';

            card.innerHTML = '\
                <div class="flex justify-between items-center">\
                    <span class="text-xs font-mono font-bold text-amber-500">' + promptId + ' (' + singlePromptObj.variant_style + ')</span>\
                    <button class="bg-stone-800 hover:bg-amber-800 text-stone-300 hover:text-white px-2.5 py-1 rounded text-[11px] font-mono transition-all cursor-pointer border border-stone-700" onclick="copySinglePrompt(\'' + promptId + '\')" id="btn-' + promptId + '">\
                        Copy JSON Object\
                    </button>\
                </div>\
                <div class="bg-stone-950 p-3 rounded-lg border border-stone-850 overflow-x-auto">\
                    <pre class="font-mono text-emerald-400 whitespace-pre-wrap text-[11px]" id="code-' + promptId + '">' + escapeHtml(jsonString) + '</pre>\
                </div>\
            ';

            outputContainer.appendChild(card);
            promptCounter++;
        }
    }
}

function escapeHtml(text) {
    return text
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

function copySinglePrompt(id) {
    var codeText = document.getElementById('code-' + id).innerText;
    var btn = document.getElementById('btn-' + id);

    navigator.clipboard.writeText(codeText).then(function() {
        var originalText = btn.innerText;
        btn.innerText = "Copied! ✓";
        btn.style.backgroundColor = "#065f46";

        setTimeout(function() {
            btn.innerText = originalText;
            btn.style.backgroundColor = "#27272a";
        }, 2000);
    }).catch(function(err) {
        alert("Gagal menyalin teks.");
    });
}

function toggleZenMode() {
    var body = document.getElementById('appBody');
    var exitBtn = document.getElementById('exitZenBtn');
    body.classList.toggle('zen-mode-active');

    if (body.classList.contains('zen-mode-active')) {
        exitBtn.classList.remove('hidden');
    } else {
        exitBtn.classList.add('hidden');
    }
}

document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && document.getElementById('appBody').classList.contains('zen-mode-active')) {
        toggleZenMode();
    }
});

function resetInputs() {
    document.getElementById('subjectInput').value = '';
    document.getElementById('imageUrlInput').value = '';
    document.getElementById('conditionInput').selectedIndex = 0;
    document.getElementById('imageSimilarityInput').value = 50;
    document.getElementById('imageSimilarityVal').innerText = '50%';
    document.getElementById('poseStyleInput').value = 40;
    document.getElementById('poseStyleVal').innerText = 'Semi Formal (Medium)';
    document.getElementById('ageStyleInput').value = 35;
    document.getElementById('ageStyleVal').innerText = 'Mature Adult (Thirties)';
    document.getElementById('jsonOutputArea').innerHTML = '<div class="text-amber-200/80 font-mono">// Input telah di-reset. Masukkan subjek baru lalu tekan tombol Generate.</div>';
}

function refreshToDefault() {
    document.getElementById('subjectInput').value = 'A busy traditional market center';
    document.getElementById('imageUrlInput').value = '';
    document.getElementById('conditionInput').value = 'pristine';
    document.getElementById('imageSimilarityInput').value = 50;
    document.getElementById('imageSimilarityVal').innerText = '50%';
    document.getElementById('poseStyleInput').value = 40;
    document.getElementById('poseStyleVal').innerText = 'Semi Formal (Medium)';
    document.getElementById('ageStyleInput').value = 35;
    document.getElementById('ageStyleVal').innerText = 'Mature Adult (Thirties)';
    document.getElementById('jsonOutputArea').innerHTML = '<div class="text-amber-200/80 font-mono">// Tekan tombol "Generate" untuk menyusun database JSON prompt otomatis...</div>';

    if (document.getElementById('appBody').classList.contains('zen-mode-active')) {
        toggleZenMode();
    }
}
//
